/// One **required** method per labelled alternative.
///
/// Each takes the alternative's bindings, already evaluated — the
/// generated evaluator does the walking. Nothing is defaulted: adding
/// an alternative to the grammar must break the build until a handler
/// exists.
pub trait Handlers: Operators + Sized {

    /// `program` — from `rule program = SOI body:stmt* EOI -> program`.
    /// * `body` — the value of the `stmt` rule, already evaluated (repeated in the grammar; items that failed and were already reported are omitted)
    fn program(&mut self, body: Vec<Self::Out>, cx: &mut Ctx) -> Result<Self::Out>;

    /// `stmt_declare` — from `rule stmt = "let" name:IDENT "=" value:expr ";" -> declare`.
    /// * `name` — the text of the `IDENT` token
    /// * `value` — the value of the `expr` rule, already evaluated
    fn stmt_declare(&mut self, name: &str, value: Self::Out, cx: &mut Ctx) -> Result<Self::Out>;

    /// `stmt_show` — from `rule stmt = "show" value:expr ";" -> show`.
    /// * `value` — the value of the `expr` rule, already evaluated
    fn stmt_show(&mut self, value: Self::Out, cx: &mut Ctx) -> Result<Self::Out>;

    /// `stmt_branch` — from `rule stmt = "if" cond:expr lazy then:block lazy otherwise:else_tail? -> branch`.
    /// * `cond` — the value of the `expr` rule, already evaluated
    /// * `then` — the `block` rule, **unevaluated** — `.eval(host, cx)?` runs it
    /// * `otherwise` — the `else_tail` rule, **unevaluated** — `.eval(host, cx)?` runs it (optional in the grammar)
    fn stmt_branch(&mut self, cond: Self::Out, then: &Shared<Block>, otherwise: Option<&Shared<ElseTail>>, cx: &mut Ctx) -> Result<Self::Out>;

    /// `stmt_loop` — from `rule stmt = "while" lazy cond:expr lazy body:block -> loop`.
    /// * `cond` — the `expr` rule, **unevaluated** — `.eval(host, cx)?` runs it
    /// * `body` — the `block` rule, **unevaluated** — `.eval(host, cx)?` runs it
    fn stmt_loop(&mut self, cond: &Shared<Expr>, body: &Shared<Block>, cx: &mut Ctx) -> Result<Self::Out>;

    /// `stmt_frame` — from `rule stmt = "begin" "frame" lazy body:stmt* "end" "frame" -> frame`.
    /// * `body` — the `stmt` rule, **unevaluated** — `.eval(host, cx)?` runs it (repeated in the grammar)
    fn stmt_frame(&mut self, body: &[Shared<Stmt>], cx: &mut Ctx) -> Result<Self::Out>;

    /// `stmt_evaluate` — from `rule stmt = value:expr ";" -> evaluate`.
    /// * `value` — the value of the `expr` rule, already evaluated
    fn stmt_evaluate(&mut self, value: Self::Out, cx: &mut Ctx) -> Result<Self::Out>;

    /// `block` — from `rule block = "{" body:stmt* "}" -> block`.
    /// * `body` — the value of the `stmt` rule, already evaluated (repeated in the grammar; items that failed and were already reported are omitted)
    fn block(&mut self, body: Vec<Self::Out>, cx: &mut Ctx) -> Result<Self::Out>;

    /// `atom_number` — from `rule atom = value:NUMBER -> number`.
    /// * `value` — the text of the `NUMBER` token
    fn atom_number(&mut self, value: &str, cx: &mut Ctx) -> Result<Self::Out>;

    /// `atom_text` — from `rule atom = text:TEXT -> text`.
    /// * `text` — the text of the `TEXT` token
    fn atom_text(&mut self, text: &str, cx: &mut Ctx) -> Result<Self::Out>;

    /// `atom_name` — from `rule atom = name:IDENT -> name place`.
    /// * `name` — the text of the `IDENT` token
    fn atom_name(&mut self, name: &str, cx: &mut Ctx) -> Result<Self::Out>;

    /// `atom_point` — from `rule atom = "(" x:expr "," y:expr ")" -> point`.
    /// * `x` — the value of the `expr` rule, already evaluated
    /// * `y` — the value of the `expr` rule, already evaluated
    fn atom_point(&mut self, x: Self::Out, y: Self::Out, cx: &mut Ctx) -> Result<Self::Out>;
}

